function isSubstringPresent(s) {
  const pairs = new Set();
  for (let i = 0; i + 1 < s.length; i++) {
    pairs.add(s[i] + s[i + 1]);
  }
  for (let i = 0; i + 1 < s.length; i++) {
    const flipped = s[i + 1] + s[i];
    if (pairs.has(flipped)) {
      return true;
    }
  }
  return false;
}

