function generate(rand, size) {
  const letters = 'abcdefghijklmnopqrstuvwxyz';
  const pickLetters = (count) => {
    const pool = letters.split('');
    const chosen = [];
    for (let i = 0; i < count; i++) chosen.push(pool.splice(Math.floor(rand() * pool.length), 1)[0]);
    return chosen;
  };
  const n = size === 'large' ? 60 + Math.floor(rand() * 41) : 1 + Math.floor(rand() * 8);
  if (rand() < 0.4) {
    // Cycling through 3 or more distinct letters never creates a pair together with its reverse.
    const cycle = pickLetters(3 + Math.floor(rand() * (size === 'large' ? 24 : 4)));
    let s = '';
    for (let i = 0; i < n; i++) s += cycle[i % cycle.length];
    return [s];
  }
  const alphabet = pickLetters(size === 'large' ? 5 + Math.floor(rand() * 22) : 2 + Math.floor(rand() * 4));
  let s = '';
  for (let i = 0; i < n; i++) s += alphabet[Math.floor(rand() * alphabet.length)];
  return [s];
}
